public void testTaskIdNotFound() {
    String taskIdNotFound = "notFound";
    final DefaultHttpResponse incorrectResponse = new DefaultHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.NOT_FOUND);
    SettableFuture<TaskStatusResponse> settableFuture = SettableFuture.create();
    settableFuture.setException(new HttpResponseException(new StringFullResponseHolder(incorrectResponse, StandardCharsets.UTF_8)));
    Mockito.when(overlordClient.taskStatus(taskIdNotFound)).thenReturn(settableFuture);
    Assert.assertEquals(Response.Status.NOT_FOUND.getStatusCode(), resource.doGetStatus(taskIdNotFound, makeOkRequest()).getStatus());
    Assert.assertEquals(Response.Status.NOT_FOUND.getStatusCode(), resource.doGetResults(taskIdNotFound, null, null, makeOkRequest()).getStatus());
    Assert.assertEquals(Response.Status.NOT_FOUND.getStatusCode(), resource.deleteQuery(taskIdNotFound, makeOkRequest()).getStatus());
}

