@Test
public void testSerde() throws JsonProcessingException {
    ObjectMapper mapper = new DefaultObjectMapper();
    mapper.registerModules(new MySQLMetadataStorageModule().getJacksonModules());
    mapper.setInjectableValues(new InjectableValues.Std().addValue(JdbcAccessSecurityConfig.class, INJECTED_CONF).addValue(MySQLConnectorDriverConfig.class, mySQLConnectorDriverConfig));
    MetadataStorageConnectorConfig connectorConfig = new MetadataStorageConnectorConfig() {

        @Override
        public String getConnectURI() {
            return "jdbc:mysql://localhost:3306/test";
        }
    };
    MySQLInputSourceDatabaseConnector connector = new MySQLInputSourceDatabaseConnector(connectorConfig, null, INJECTED_CONF, mySQLConnectorDriverConfig);
    MySQLInputSourceDatabaseConnector andBack = mapper.readValue(mapper.writeValueAsString(connector), MySQLInputSourceDatabaseConnector.class);
    Assert.assertEquals(connector, andBack);
    // test again with classname
    connector = new MySQLInputSourceDatabaseConnector(connectorConfig, "some.class.name.Driver", INJECTED_CONF, mySQLConnectorDriverConfig);
    andBack = mapper.readValue(mapper.writeValueAsString(connector), MySQLInputSourceDatabaseConnector.class);
    Assert.assertEquals(connector, andBack);
